```text
// existing class with an incompatible interface
class LegacyLogger:
    method write(message):
        print("[legacy] " + message)

// target interface the client code expects
interface Logger:
    method log(message)

// adapter implements the target, wraps the legacy object
class LoggerAdapter implements Logger:
    field legacy

    constructor(legacyLogger):
        this.legacy = legacyLogger

    method log(message):
        this.legacy.write(message)   // translate the call

// client only ever talks to Logger
function runApp(logger: Logger):
    logger.log("starting up")

runApp(new LoggerAdapter(new LegacyLogger()))
```

```text
// complex subsystem — many small classes, precise call order
class CPU:
    method boot(): print("cpu booted")

class Memory:
    method load(): print("memory loaded")

class Disk:
    method spinUp(): print("disk ready")

// facade hides the coordination behind one call
class ComputerFacade:
    field cpu = new CPU()
    field memory = new Memory()
    field disk = new Disk()

    method startComputer():
        this.disk.spinUp()
        this.cpu.boot()
        this.memory.load()

// client just calls the facade
computer = new ComputerFacade()
computer.startComputer()
```
